import{_ as t,o as c,c as r,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"LLVM 补丁","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"LLVM 补丁 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/patches"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/patches"}]]},"headers":[],"relativePath":"zh/xclang/reference/patches.md","filePath":"zh/xclang/reference/patches.md","lastUpdated":1794512045000}'),o={name:"zh/xclang/reference/patches.md"};function d(l,e,i,n,s,h){return c(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="llvm-补丁" tabindex="-1">LLVM 补丁 <a class="header-anchor" href="#llvm-补丁" aria-label="Permalink to &quot;LLVM 补丁&quot;">​</a></h1><p>xclang 基于 LLVM 官方发布源码包 <code>llvm-project-&lt;version&gt;.src.tar.xz</code> 构建编译器、链接器、运行时库与 libclang，并打上了 <a href="https://github.com/clice-io/xclang/tree/main/patches" target="_blank" rel="noreferrer"><code>patches/</code></a> 目录下的补丁。每个补丁的 README 都说明了未打补丁时的问题表现、具体修改内容、验证方式以及上游推进状态。</p><h2 id="补丁列表" tabindex="-1">补丁列表 <a class="header-anchor" href="#补丁列表" aria-label="Permalink to &quot;补丁列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>补丁</th><th>修改内容</th></tr></thead><tbody><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0001-sema-partial-ordering-depth/README.md" target="_blank" rel="noreferrer"><code>0001-sema-partial-ordering-depth</code></a></td><td>偏序关系按模板自身的嵌套深度推导：在类模板内触发代码补全不再导致 clang 崩溃（<a href="https://github.com/clice-io/clice/issues/701" target="_blank" rel="noreferrer">clice#701</a>）</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0002-completion-unresolved-member-base/README.md" target="_blank" rel="noreferrer"><code>0002-completion-unresolved-member-base</code></a></td><td>当 Sema 无法解析基表达式的类类型时，成员访问代码补全仍会报告其上下文</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0003-completion-context-base-expr/README.md" target="_blank" rel="noreferrer"><code>0003-completion-context-base-expr</code></a></td><td>新增 <code>CodeCompletionContext::getBaseExpr</code>，返回源码中书写的成员访问基表达式</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0004-windows-driver-setup-api-mingw/README.md" target="_blank" rel="noreferrer"><code>0004-windows-driver-setup-api-mingw</code></a></td><td>让 MinGW 编译的 clang 与 MSVC 编译版本一样，通过 Setup API 查找 Visual Studio 2017 及更高版本（<a href="https://github.com/clice-io/clice/issues/714" target="_blank" rel="noreferrer">clice#714</a>）</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0007-lld-macho-empty-section-unwind/README.md" target="_blank" rel="noreferrer"><code>0007-lld-macho-empty-section-unwind</code></a></td><td>当空节中的符号与某个函数共用同一地址时，ld64.lld 仍保留这个函数的栈展开条目：使单条 clang 命令链接的 ThinLTO 程序在 arm64 macOS 上能够正常捕获异常</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0008-preprocessed-raw-string-lines/README.md" target="_blank" rel="noreferrer"><code>0008-preprocessed-raw-string-lines</code></a></td><td><code>clang -E</code> 将原始字符串字面量中的 CRLF 换行符按其实际语义写为 <code>\\n</code> 并准确统计行数：编译预处理输出时（如 xmake 等构建缓存），能够得到相同的字符串内容与行号</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0010-windows-stack-trace/README.md" target="_blank" rel="noreferrer"><code>0010-windows-stack-trace</code></a></td><td>在 arm64 Windows 上打印崩溃调用栈时，能够穿过返回地址带指针签名的系统 DLL 栈帧：在 C 标准库回调中崩溃或从信号处理函数打印调用栈时，能够回溯到触发崩溃的代码位置</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0011-clang-cl-config-pass-through/README.md" target="_blank" rel="noreferrer"><code>0011-clang-cl-config-pass-through</code></a></td><td>clang-cl 不再将配置文件中的选项（包括通过 <code>/clang:</code> 透传的选项）报为未使用：使 MSVC 目标平台的 C 代码能够在开启 <code>/WX</code> 时正常编译</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0012-msvc-compiler-rt-libpath-first/README.md" target="_blank" rel="noreferrer"><code>0012-msvc-compiler-rt-libpath-first</code></a></td><td>clang 链接 MSVC 目标平台时，将自身的 compiler-rt 排在 Visual Studio 的 <code>clang_rt.*.lib</code> 之前：未下载 SDK 时，<code>__int128</code> 除法、UBSan 与 libFuzzer 也能正常链接</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0013-runtime-dir-pc-vendor/README.md" target="_blank" rel="noreferrer"><code>0013-runtime-dir-pc-vendor</code></a></td><td>让 GCC 风格的写法 <code>--target=x86_64-pc-linux-gnu</code>、<code>x86_64-pc-windows-gnu</code> 以及 <code>arm64-linux-gnu</code>、<code>arm64-w64-mingw32</code> 能够在标准目录名下找到 compiler-rt 并正常链接</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0014-coff-timestamp-default/README.md" target="_blank" rel="noreferrer"><code>0014-coff-timestamp-default</code></a></td><td>恢复 LLVM 22 及 GNU 工具的行为，不在 MinGW 目标平台的 COFF 目标文件头部写入编译时间戳：相同源码编译出逐字节相同的目标文件（llvm/llvm-project#222099）</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0016-libcxx-vcruntime/README.md" target="_blank" rel="noreferrer"><code>0016-libcxx-vcruntime</code></a></td><td>基于 vcruntime 构建的 libc++ 不再重复定义由 C 运行时提供的 <code>std::nothrow</code>，并自行提供原本仅在微软 STL 库中定义的 <code>std::set_new_handler</code> 与 <code>get_new_handler</code></td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0017-lld-coff-call-graph-order/README.md" target="_blank" rel="noreferrer"><code>0017-lld-coff-call-graph-order</code></a></td><td>lld-link 在每次链接开启 PGO 的程序时采用一致的布局：不同目标文件中的同名局部函数不再在多次链接之间发生顺序漂移</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0018-stdlib-system-config/README.md" target="_blank" rel="noreferrer"><code>0018-stdlib-system-config</code></a></td><td>当 <code>-stdlib=</code> 指定 libc++ 以外的标准库（<code>platform</code>、<code>libstdc++</code>；clang-cl 中为 <code>/clang:-stdlib=platform</code>）时，自动切换到目标平台的 <code>&lt;triple&gt;-system.cfg</code>：在所有目标平台上改用平台的 C++ 标准库及其 sysroot（<a href="./../guide/cross-compiling#the-platform-s-c-library">系统的 C++ 标准库</a>）</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0019-msvc-exception-copy-ctor-ast/README.md" target="_blank" rel="noreferrer"><code>0019-msvc-exception-copy-ctor-ast</code></a></td><td>MSVC 目标平台上，C++20 模块或 PCH 中抛出的类型，在 import 它的文件生成的 catchable type 里保留拷贝构造函数：<code>std::exception_ptr</code> 调用它复制异常对象，而不是逐字节复制（<a href="https://github.com/clice-io/xclang/issues/27" target="_blank" rel="noreferrer">xclang#27</a>）</td></tr></tbody></table><h2 id="补丁应用方式" tabindex="-1">补丁应用方式 <a class="header-anchor" href="#补丁应用方式" aria-label="Permalink to &quot;补丁应用方式&quot;">​</a></h2><p>解压 LLVM 源码后，<code>toolchain/common.ts</code> 会立即按目录顺序使用 <code>patch -p1 -F0 --forward</code> 应用每个 <code>patches/NNNN-name/NNNN.patch</code>：禁用模糊匹配（fuzz），只要补丁位置发生偏移就会直接令构建失败。每个工具链在 <code>libc++/src</code> 下随附的运行时库源码也会打上其中涉及自身文件的补丁（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）。libclang 的 <code>lib/cmake/xclang/libclang.cmake</code> 则会在 <code>XCLANG_PATCHES</code> 中记录已应用的补丁列表（<a href="./cmake-api">CMake API</a>）。</p><h2 id="补丁目录结构" tabindex="-1">补丁目录结构 <a class="header-anchor" href="#补丁目录结构" aria-label="Permalink to &quot;补丁目录结构&quot;">​</a></h2><ul><li>一个 <code>patches/NNNN-short-name/</code> 目录，内含一份基于 LLVM 发布标签生成的 <code>git diff</code> 补丁文件 <code>NNNN.patch</code>，以及一份 <code>README.md</code>：记录问题现象与触发场景、补丁修改内容、上游状态（<code>Upstream:</code>）、补丁来源（<code>From:</code>）以及验证方式（<code>Checked:</code>）。</li><li>一项在未打这个补丁时会失败的测试，位于 <code>tests/toolchain/smoke.ts</code>（在每个主机的工具链上运行）、<code>tests/cmake</code> 或 <code>tests/bazel</code> 中。</li><li>永不复用的补丁编号：已被上游合入的补丁会在升级到包含对应修复的 LLVM 版本时删除。</li></ul>',8)])])}const g=t(o,[["render",d]]);export{m as __pageData,g as default};
